WITH session_totals AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_purchase, COUNT(*) AS num_web_events FROM web_events WHERE page IN ('/home', '/product', '/search') GROUP BY session_id) SELECT s.id, s.browser, st.pct_purchase, st.num_web_events FROM sessions s LEFT JOIN session_totals st ON s.id = st.session_id ORDER BY s.id DESC;
